%[text] **Personal finance and Savings analyser**
%[text] This project uses Matlab to analyse monthly income, expenditure and savings, generate financial visualisations, and forecast progress towards saving goals.
%%\ PERSONAL FINANCE & SAVINGS ANALYSER
% Project: Personal Finance and Savings Analyser
% Language: MATLAB
%
% Description:
% Analyses monthly income, expenses and savings.
% Imports financial data from a CSV file.
% Calculates financial performance indicators.
% Forecasts savings growth towards a target.
% Compares different monthly savings scenarios.
%
% Data: Fictional sample financial records.

% Part 1 
clear;
clc;
close all;

% Look for CSV file in the current folder
csvFile = 'sample_financial_data.csv';

% To check if the CSV file exists
if ~isfile(csvFile)
    error('CSV file not found. Open the project folder first.');
end

% Importing financial data
importedData = readtable(csvFile);

% Extract months, income and expenses
months = string(importedData.Month)';
income = importedData.Income';
expenses = importedData.Expenses';

% Display imported data
disp(importedData); %[output:0b5b6d56]

% Display the financial data
financialData = table(months', income', expenses', ...
    'VariableNames', ["months", "income", "expenses"]);
disp(financialData) %[output:5fe3e357]
%%
if length(months) ~= length(income) || ...
        length(income) ~= length(expenses)
    error("Months, income and expenses must have matching lengths.");
end

if ~isnumeric(income) || ~isnumeric(expenses)
    error("Income and expenses must contain numeric values.");
end

if any(~isfinite(income)) || any(~isfinite(expenses))
    error('Income and expenses must contain finite numbers.');
end

if any(income < 0) || any(expenses < 0)
    error('Income and expenses cannot be negative.');
end

if any(income == 0)
    error('Monthly income must be greater than zero for savings rates.');
end

disp("Data validation successful."); %[output:5ea79c78]
%%
% Part 2
% Calculate the monthly savings
savings = income - expenses;

% Add savings to financialData
financialData.savings = savings';

% Display the updated table
financialData.savingsRate = (savings ./ income)' * 100;
disp(financialData) %[output:87671ce1]

%%
% Part 3
% Calculate total income, expenses and savings
totalIncome = sum(income);
totalExpenses = sum(expenses);
totalSavings = sum(savings);

% Calculate average monthly savings
averageSavings = mean(savings);

% Calculate overall savings rate
savingsRate = (totalSavings / totalIncome) * 100;

% Display results
fprintf('Total income: £%.2f\n', totalIncome); %[output:96e34dba]
fprintf('Total Expenses: £%.2f\n', totalExpenses); %[output:6b745369]
fprintf('Total Savings: £%.2f\n', totalSavings); %[output:006c6b03]
fprintf('Average Monthly Savings: £%.2f\n', averageSavings); %[output:6febbf5d]
fprintf('Savings Rate: %.2f%%\n', savingsRate); %[output:51f67d1c]
%%
% Part 4
figure; %[output:26d493ca]

% Plot monthly income and expenses
bar([income' expenses']); %[output:26d493ca]

% Add chart title and axis label
title("Monthly Income vs Expenses"); %[output:26d493ca]
xlabel("Month"); %[output:26d493ca]
ylabel("Amount (£)"); %[output:26d493ca]

% To display the months along the X-axis
xticks(1:length(months)); %[output:26d493ca]
xticklabels(months); %[output:26d493ca]

% Adding legend and grid
legend("Income", "Expenses"); %[output:26d493ca]
grid on; %[output:26d493ca]
%%
% Part 5
% Calculating cumulative savings
cumulativeSavings = cumsum(savings);

% To create a new figure
figure; %[output:6aa0cd60]

% Plot cumulative savings
plot(1:length(months), cumulativeSavings, ... %[output:6aa0cd60]
    "-o","LineWidth", 2); %[output:6aa0cd60]

% Adding graph title and Labels
title("Cumulative Savings Growth"); %[output:6aa0cd60]
xlabel("Month"); %[output:6aa0cd60]
ylabel("Total Savings (£)"); %[output:6aa0cd60]

% To display the months along the X-axis
xticks(1:length(months)); %[output:6aa0cd60]
xticklabels(months); %[output:6aa0cd60]

% To add grid lines
grid on; %[output:6aa0cd60]
%%
% Part 6
% Set a savings target
savingsTarget = 5000;

% Calculate how much more money is needed
remainingSavings = max(0,savingsTarget - totalSavings);

% Calculate how many months required
if remainingSavings == 0 
    monthsRequired = 0;
elseif averageSavings > 0
    monthsRequired = ceil(remainingSavings / averageSavings);
else
    monthsRequired = Inf;
end

% Display the predictions
fprintf("Savings Goal: £%.2f\n", savingsTarget); %[output:4e3b1b00]
fprintf("Remaining Savings Needed: £%.2f\n", remainingSavings); %[output:80d1430b]

if isinf(monthsRequired) %[output:group:3a8a4314]
    fprintf("Goal can't be reached at the current savings rate.\n");
else
    fprintf("Additional months required: %d\n", monthsRequired); %[output:88f835a4]
end %[output:group:3a8a4314]
%%
% Part 7
% Creating an array to represent future months
futureMonths = 0:monthsRequired;

% Calculate projected savings for each month
projectedSavings = totalSavings + ...
    (averageSavings * futureMonths);

figure; %[output:068e1502]
plot(futureMonths, projectedSavings, ... %[output:068e1502]
    "-o", 'LineWidth', 2); %[output:068e1502]
hold on; %[output:068e1502]
yline(savingsTarget, "--r", "Savings Goal"); %[output:068e1502]

% Adding graph title and labels
title("Projected Savings Growth"); %[output:068e1502]
xlabel("Additional Months"); %[output:068e1502]
ylabel("Total Savings (£)"); %[output:068e1502]

% Adding grid lines
grid on; %[output:068e1502]

hold off; %[output:068e1502]
%%
% Part 8
% Calculate savings rate for each month
monthlySavingsRate = (savings ./ income) * 100;

% Adding savings rates to financial table
financialData.SavingsRate = monthlySavingsRate';

disp(financialData); %[output:1b5252d1]

% Finding the highest and lowest savings rate
[highestRate, highestIndex] = max(monthlySavingsRate);
[lowestRate, lowestIndex] = min(monthlySavingsRate);

fprintf("Highest Savings Rate: %s (%.2f%%)\n", ... %[output:group:30e62c78] %[output:649ecc30]
    months(highestIndex),highestRate); %[output:group:30e62c78] %[output:649ecc30]
fprintf("Lowest Savings Rate: %s (%.2f%%)\n", ... %[output:group:354a9a3e] %[output:3d256b9b]
    months(lowestIndex),lowestRate); %[output:group:354a9a3e] %[output:3d256b9b]

% Creating a bar chart for savings rate
figure; %[output:915eee09]
bar(monthlySavingsRate); %[output:915eee09]
title("Monthly Savings Rate"); %[output:915eee09]
xlabel("Month"); %[output:915eee09]
ylabel("Savings Rate (%)"); %[output:915eee09]

xticks(1:length(months)); %[output:915eee09]
xticklabels(months); %[output:915eee09]
grid on; %[output:915eee09]
%%
% Part 9 
scenarioNames = ["Conservative", "Current Average", "Optimistic"];
scenarioSavings = [300, averageSavings, 600];

% Calculating the remaining savings
remainingAmount = max(0, savingsTarget - totalSavings);

% Calculating the months required
scenarioMonths = ceil(remainingAmount ./ scenarioSavings);

% Create comparison table
scenarioTable = table( ...
    scenarioNames(:), ...
    scenarioSavings(:), ...
    scenarioMonths(:));

% Assign column names separately
scenarioTable.Properties.VariableNames = ...
    {'Scenario', 'MonthlySavings', 'MonthsRequired'};

% Display results
disp(scenarioTable); %[output:451b1132]

disp(scenarioTable); %[output:1a5cf852]
%%
% Part 10
% Creating a timeline for the next 12 months
forecastMonths = 0:12;

% Calculating the projected savings for each scenario
conservativeGrowth = totalSavings + 300 * forecastMonths;
averageGrowth = totalSavings + averageSavings * forecastMonths;
optimisticGrowth = totalSavings + 600 * forecastMonths;

figure; %[output:6eeba565]

p1 = plot(forecastMonths, conservativeGrowth, '-o', 'LineWidth', 2); %[output:6eeba565]
hold on; %[output:6eeba565]

p2 = plot(forecastMonths, averageGrowth, '-s', 'LineWidth', 2); %[output:6eeba565]
p3 = plot(forecastMonths, optimisticGrowth, '-^', 'LineWidth', 2); %[output:6eeba565]

% Plot savings goal as a horizontal line
p4 = plot(forecastMonths, ... %[output:6eeba565]
    savingsTarget * ones(size(forecastMonths)), '--', 'LineWidth', 2); %[output:6eeba565]

% Add labels
title('Savings Scenario Comparison'); %[output:6eeba565]
xlabel('Additional Months'); %[output:6eeba565]
ylabel('Projected Savings (£)'); %[output:6eeba565]

% Assign legend labels to specific lines
legend([p1, p2, p3, p4], ... %[output:6eeba565]
    {'Conservative', 'Current Average', ... %[output:6eeba565]
    'Optimistic', 'Savings Goal'}, ... %[output:6eeba565]
    'Location', 'northwest'); %[output:6eeba565]

grid on; %[output:6eeba565]
hold off; %[output:6eeba565]

grid on; %[output:6eeba565]
hold off;   %[output:6eeba565]

